// class key → [family, talent profile]
export const TOP_DR2_CLASS_PROFILE: Readonly<Record<string, readonly [string, string]>> = {"Beginner":["beginner","base"],"Journeyman":["beginner","t24"],"Maestro":["beginner","t24"],"Voidwalker":["beginner","t24"],"Warrior":["warrior","base"],"Barbarian":["warrior","base"],"Blood_Berserker":["warrior","base"],"Death_Bringer":["warrior","base"],"Squire":["warrior","base"],"Divine_Knight":["warrior","base"],"Archer":["archer","t279"],"Bowman":["archer","t279"],"Siege_Breaker":["archer","t279"],"Hunter":["archer","t279"],"Beast_Master":["archer","t279"],"Wind_Walker":["archer","t279"],"Mage":["mage","base"],"Shaman":["mage","base"],"Bubonic_Conjuror":["mage","base"],"Arcane_Cultist":["mage","base"],"Wizard":["mage","base"],"Elemental_Sorcerer":["mage","base"],"Royal_Guardian":["warrior","t239"]};

// Family used when no class is known (the highest-reaching one).
export const TOP_DR2_DEFAULT_FAMILY = "archer";

/** The top Drop Rate V2 reference for a class — its family's base merged with its profile. */
export function topDr2FlatForClass(classKey: string | null | undefined): FlatMap {
  const [family, profile] = (classKey && TOP_DR2_CLASS_PROFILE[classKey]) || [TOP_DR2_DEFAULT_FAMILY, "base"];
  const base = TOP_DR2_FAMILY_FLAT[family] ?? TOP_DR2_FAMILY_FLAT[TOP_DR2_DEFAULT_FAMILY];
  const override = TOP_DR2_PROFILE_OVERRIDES[`${family}:${profile}`];
  return override ? { ...base, ...override } : base;
}
